use std::io::{self, Read};

fn is_valid(line: &str) -> bool {
    let mut stack = Vec::new();

    for bracket in line.bytes() {
        match bracket {
            b'(' | b'[' | b'{' => stack.push(bracket),
            b')' => {
                if stack.pop() != Some(b'(') {
                    return false;
                }
            }
            b']' => {
                if stack.pop() != Some(b'[') {
                    return false;
                }
            }
            b'}' => {
                if stack.pop() != Some(b'{') {
                    return false;
                }
            }
            _ => {}
        }
    }

    stack.is_empty()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.split('\n');
    let count: usize = lines
        .next()
        .unwrap_or("0")
        .trim_end_matches('\r')
        .parse()
        .unwrap();

    let mut output = String::new();
    for _ in 0..count {
        let line = lines.next().unwrap_or("").trim_end_matches('\r');
        output.push_str(if is_valid(line) { "valid" } else { "invalid" });
        output.push('\n');
    }

    print!("{output}");
}

