        return

    count = int(count_line)
    if count == 0:
        print()
        return

    start = previous = int(lines.readline())
    output: list[str] = []

    def append_run(run_start: int, run_end: int) -> None:
        length = run_end - run_start + 1
        if length >= 3:
            output.append(f"{run_start}-{run_end}")
        else:
            output.extend(str(value) for value in range(run_start, run_end + 1))

    for _ in range(count - 1):
        current = int(lines.readline())
        if current != previous + 1:
            append_run(start, previous)
            start = current
        previous = current

    append_run(start, previous)
    print(",".join(output))


