import sys


def compact_ranges(numbers: list[int]) -> str:
    parts: list[str] = []
    start = numbers[0]
    end = start

    for number in numbers[1:]:
        if number == end + 1:
            end = number
            continue

        append_run(parts, start, end)
        start = end = number

    append_run(parts, start, end)
    return ",".join(parts)


def append_run(parts: list[str], start: int, end: int) -> None:
    if end - start >= 2:
        parts.append(f"{start}-{end}")
    else:
        parts.extend(str(number) for number in range(start, end + 1))


def main() -> None:
    lines = sys.stdin.buffer
    count_line = lines.readline()
    if not count_line:
        return

    count = int(count_line)
    numbers = [int(lines.readline()) for _ in range(count)]
    print(compact_ranges(numbers) if numbers else "")


if __name__ == "__main__":
    main()

